SELECT 
FROM schedule sch
INNER JOIN doctor doc ON doc.id = sch.doctor_id
INNER JOIN department dept ON dept.id = doc.department_id

    sch.status = 1
    AND doc.status = 1
    AND dept.status = 1
    AND CONCAT(sch.work_date, ' ', sch.start_time) > NOW()

        AND sch.doctor_id = #{doctorId}


        AND doc.department_id = #{departmentId}


        AND sch.work_date >= #{startDate}


        AND sch.work_date <= #{endDate}


        AND sch.period = #{period}


        AND sch.available_slots > 0


ORDER BY sch.work_date ASC, sch.start_time ASC, doc.id ASC
LIMIT 500

SELECT id, doctor_id, work_date, period, start_time, end_time,
       total_slots, available_slots, registration_fee, status, create_time, update_time
FROM schedule
WHERE doctor_id = #{doctorId}
  AND work_date = #{workDate}
  AND period = #{period}
LIMIT 1

mapper.update:
UPDATE schedule
SET status = #{status}, update_time = NOW()
WHERE id = #{id}
